void printUnsignedLine(unsigned int unsignedNumber) {
    printf("%u\n", unsignedNumber);
}

static void goodG2B(void) {
    unsigned int data = 0;
    data = (unsigned int)-2;
    data--;
    printUnsignedLine(data);
}

