    unsigned int data = 0;
    fscanf(stdin, "%u", &data);
    if (data > 0) {
        data--;
        printUnsignedLine(data);
    } else {
        printLine("data value is too large to perform arithmetic safely.");
    }
}

static void good(void) {
    goodG2B();
    goodB2G();
}

